class Solution:
    def calculateScore(self, s: str) -> int:
        # Create a mapping of each character to its mirror
        mirror = {chr(ord('a') + i): chr(ord('z') - i) for i in range(26)}
        # Use a stack to keep track of indices of characters that can potentially be mirrored
        stack = []
        score = 0

        for i, char in enumerate(s):
            mirror_char = mirror[char]
            # Check if the mirror character is in the stack
            for j in reversed(stack):
                if s[j] == mirror_char:
                    # Found the closest unmarked index j
                    score += i - j
                    stack.remove(j)  # Mark the index j as used
                    break
            stack.append(i)  # Add current index to the stack

        return score
