class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        from collections import defaultdict

        # dp[prev][diff] = max length of subsequence ending with 'prev' with last difference 'diff'
        dp = defaultdict(dict)

        for i in range(len(nums)):
            num = nums[i]
            # Start a new subsequence with just this number
            dp[num][0] = 1

            # Check all previous numbers
            for prev in dp:
                for diff in dp[prev]:
                    new_diff = abs(num - prev)
                    if new_diff not in dp[num] or dp[prev][diff] + 1 > dp[num][new_diff]:
                        dp[num][new_diff] = dp[prev][diff] + 1

        # Find the maximum length across all subsequences
        max_len = 0
        for d in dp.values():
            max_len = max(max_len, max(d.values(), default=0))
        return max_len
