from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        max_sum = float('-inf')
        current_sum = 0
        max_without_deletion = float('-inf')
        current_without_deletion = 0

        # Compute maximum subarray sum without any deletion
        for num in nums:
            current_sum = max(num, current_sum + num)
            max_sum = max(max_sum, current_sum)

        # Compute maximum subarray sum after deleting one element
        for i in range(len(nums)):
            # Remove nums[i] and compute max subarray sum
            # We can do this by considering the max subarray sum from left and right
            left = nums[:i]
            right = nums[i+1:]
            if not left and not right:
                continue
            elif not left:
                current = max(self.kadane(right))
            elif not right:
                current = max(self.kadane(left))
            else:
                current = max(self.kadane(left), self.kadane(right))
            max_without_deletion = max(max_without_deletion, current)

        return max(max_sum, max_without_deletion)

    def kadane(self, arr: List[int]) -> int:
        max_ending_here = max_so_far = float('-inf')
        for num in arr:
            max_ending_here = max(num, max_ending_here + num)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far
